import React from "react";
import { Link } from "react-router-dom";

export default function Logo({ dark = false, size = "md" }) {
  const scales = { sm: 0.7, md: 1, lg: 1.4 };
  const s = scales[size] || 1;

  return (
    <Link to="/" className="flex items-center gap-2.5 group select-none">
      {/* Emblem mark */}
      <svg
        width={Math.round(36 * s)}
        height={Math.round(36 * s)}
        viewBox="0 0 36 36"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        className="flex-shrink-0"
      >
        {/* Outer circle */}
        <circle cx="18" cy="18" r="17" stroke="#C9A84C" strokeWidth="1"/>
        {/* Inner thin circle */}
        <circle cx="18" cy="18" r="13.5" stroke="#C9A84C" strokeWidth="0.4" strokeDasharray="2 2"/>
        {/* Stylised nut / leaf shape in center */}
        <path
          d="M18 8 C22 8 26 12 26 18 C26 24 22 28 18 28 C14 28 10 24 10 18 C10 12 14 8 18 8Z"
          fill="#C9A84C"
          opacity="0.12"
        />
        {/* J + S lettermark */}
        <text
          x="18"
          y="21"
          textAnchor="middle"
          fontFamily="Georgia, serif"
          fontSize="11"
          fontWeight="600"
          fill="#C9A84C"
          letterSpacing="0.5"
        >JS</text>
        {/* Top ornament dots */}
        <circle cx="18" cy="3.5" r="1" fill="#C9A84C"/>
        <circle cx="18" cy="32.5" r="1" fill="#C9A84C"/>
        <circle cx="3.5" cy="18" r="1" fill="#C9A84C"/>
        <circle cx="32.5" cy="18" r="1" fill="#C9A84C"/>
      </svg>

      {/* Brand name */}
      <div className="flex flex-col leading-none">
        <span
          className={`font-serif font-bold tracking-widest uppercase ${dark ? "text-white" : "text-brand-brown"} group-hover:text-brand-gold transition-colors`}
          style={{ fontSize: Math.round(15 * s), letterSpacing: "0.18em" }}
        >
          Jai Shree
        </span>
        <span
          className="text-brand-gold font-semibold tracking-[0.3em] uppercase"
          style={{ fontSize: Math.round(8 * s) }}
        >
          Dryfruits
        </span>
      </div>
    </Link>
  );
}
